import "server-only";
import { parentText, type ParentLocale } from "./locale";

/** Published information copy stays on its server pages rather than in every account bundle. */
export function publicInfoText(locale: ParentLocale, english: string): string {
  return locale === "es" && Object.hasOwn(spanish, english) ? spanish[english as keyof typeof spanish] : parentText(locale, english);
}

const spanish = {
  "Help, without another hurdle.": "Ayuda sin más obstáculos.",
  "You can use official programs directly at any time. You do not need to create a CaseLink account or upload a document first.": "Puede acudir directamente a los programas oficiales en cualquier momento. No necesita crear una cuenta de CaseLink ni subir primero un documento.",
  "Need food or utility help now?": "¿Necesita comida o ayuda con los servicios públicos ahora?",
  "For food today, use the City’s food and meal finder. Check the location’s current hours and access requirements before traveling.": "Para conseguir comida hoy, use el buscador de alimentos y comidas de la Ciudad. Antes de ir, compruebe los horarios actuales del lugar y sus requisitos de acceso.",
  "For a shutoff notice or disconnected service, contact your utility’s official assistance channel directly. Tell them the notice date and whether service is already off. A CaseLink request or assistance application does not confirm a shutoff hold.": "Si recibió un aviso de corte o ya no tiene servicio, contacte directamente con el canal oficial de asistencia de su compañía de servicios públicos. Indique la fecha del aviso y si el servicio ya está cortado. Una solicitud de apoyo en CaseLink o una solicitud de asistencia no confirma que se haya suspendido el corte.",
  "PECO assistance": "Asistencia de PECO",
  "PGW financial support": "Apoyo económico de PGW",
  "Philadelphia water assistance": "Asistencia para el agua en Filadelfia",
  "Published program information does not establish available funding, appointments or a reservation. CaseLink does not currently offer a staffed emergency line.": "La información publicada sobre un programa no confirma que haya fondos, citas o una reserva disponibles. CaseLink no ofrece actualmente una línea de emergencias atendida por personal.",
  "Official programs & partner options": "Programas oficiales y opciones de organizaciones asociadas",
  "Can’t sign in?": "¿No puede iniciar sesión?",
  "For an existing CaseLink school account, use your email and password. If you forgot it,": "Si tiene una cuenta escolar de CaseLink, use su correo electrónico y contraseña. Si la olvidó,",
  "reset your existing password": "restablezca su contraseña actual",
  "If you use email-code sign-in, choose “Use an email code instead.” Use the same email address as your account, check spam or junk mail, and use the newest code.": "Si inicia sesión con un código por correo electrónico, elija «Usar un código por correo electrónico». Use la misma dirección de su cuenta, revise la carpeta de correo no deseado y utilice el código más reciente.",
  "Never share your password or codes. If you no longer have access to your email, CaseLink does not currently provide an automatic account transfer; contact the program directly for time-sensitive support.": "No comparta nunca su contraseña ni sus códigos. Si ya no tiene acceso a su correo electrónico, CaseLink no ofrece actualmente un traslado automático de la cuenta; contacte directamente con el programa si necesita apoyo urgente.",
  "Return to sign in": "Volver al inicio de sesión",
  "Something changed?": "¿Cambió algo?",
  "Open your request in": "Abra su solicitud en",
  "to correct household or bill information, add a document, pause work or cancel. For a new kind of support, start another request so its program permissions are clear.": "para corregir información del hogar o de una factura, añadir un documento, pausar el trabajo o cancelarlo. Para otro tipo de apoyo, inicie otra solicitud para que los permisos de sus programas queden claros.",
  "Want help from a person?": "¿Quiere ayuda de una persona?",
  "Use the program links above for benefits specialists and utility assistance. Do not wait for a CaseLink response when a program deadline is close.": "Use los enlaces de los programas que aparecen arriba para contactar con especialistas en beneficios y asistencia con servicios públicos. No espere una respuesta de CaseLink si se acerca la fecha límite de un programa.",
  "Privacy or account controls": "Privacidad y controles de la cuenta",
  "has notification choices, information download and deletion controls.": "incluye opciones de notificación y controles para descargar o eliminar información.",
  "Read the privacy notice": "Lea el aviso de privacidad",
  "for sharing, document processing and the limits of recalling information already sent.": "para conocer el uso compartido, el procesamiento de documentos y los límites para recuperar información ya enviada.",
  "Privacy & data policy": "Privacidad y política de datos",
  "Your information. Your control.": "Su información. Su control.",
  "Last updated November 13, 2026 · Parent service": "Última actualización: 13 de noviembre de 2026 · Servicio para familias",
  "Live personal-data processing is not open by default. Provider agreements, approved retention terms and operational privacy checks are required before a real-family pilot. Test environments must use synthetic information.": "El procesamiento de datos personales reales no está abierto de forma predeterminada. Antes de un piloto con familias reales se requieren acuerdos con proveedores, condiciones de conservación aprobadas y comprobaciones operativas de privacidad. Los entornos de prueba deben usar información sintética.",
  "CaseLink helps adults find food support and utility assistance for their household. This notice explains the parent service. Existing school records keep their separate access rules and purpose; using the same sign-in does not transfer those records into your household.": "CaseLink ayuda a personas adultas a encontrar apoyo alimentario y asistencia con servicios públicos para su hogar. Este aviso explica el servicio para familias. Los registros escolares existentes mantienen sus propias reglas de acceso y finalidad; usar el mismo inicio de sesión no transfiere esos registros a su hogar.",
  "We do not sell personal information or share it for advertising.": "No vendemos información personal ni la compartimos con fines publicitarios.",
  "You choose the programs, information and actions you authorize.": "Usted elige los programas, la información y las acciones que autoriza.",
  "Documents need separate consent before upload and processing.": "Los documentos requieren un consentimiento separado antes de subirlos y procesarlos.",
  "You can correct information, stop future work and request deletion.": "Puede corregir información, detener el trabajo futuro y solicitar la eliminación de datos.",
  "What this service uses": "Qué utiliza este servicio",
  "CaseLink’s parent service uses a verified email address, your chosen support needs, ZIP code, minimum household and routing details, your language and contact preferences, authorization and support history. Depending on the support you choose, this can include household size, whether a child is under five, pregnancy or postpartum information, income, utility details and supporting documents. Additional details are requested only when useful or required for a supported program.": "El servicio de CaseLink para familias utiliza una dirección de correo electrónico verificada, las necesidades de apoyo que elija, el código postal, los datos mínimos del hogar y de orientación a programas, sus preferencias de idioma y contacto, la autorización y el historial de apoyo. Según el apoyo que elija, esto puede incluir el tamaño del hogar, si hay un menor de cinco años, información de embarazo o posparto, ingresos, datos de servicios públicos y documentos justificativos. Solo se piden datos adicionales cuando resultan útiles o necesarios para un programa admitido.",
  "We use these details to find relevant programs, prepare permitted work, follow up, show your progress and protect the service. You can choose “Not sure” where offered and use manual alternatives. We keep the information you provide separate from a program’s verified decision or receipt.": "Usamos estos datos para encontrar programas pertinentes, preparar el trabajo permitido, hacer seguimiento, mostrar su progreso y proteger el servicio. Puede elegir «No estoy seguro/a» cuando se ofrezca y usar alternativas manuales. Mantenemos la información que usted proporciona separada de una decisión o un comprobante verificado de un programa.",
  "Do not put passwords, email codes, EBT PINs or unrequested identity documents in support requests or uploads. Enter your CaseLink password only in its sign-in form. Use only the protected personal-entry step offered for the named program for required identifiers and signatures; never put them in chat or ordinary support fields.": "No incluya contraseñas, códigos de correo electrónico, PIN de EBT ni documentos de identidad no solicitados en las solicitudes de apoyo o los archivos que suba. Introduzca su contraseña de CaseLink solo en el formulario de inicio de sesión. Para los identificadores y las firmas obligatorios, use únicamente el paso protegido de entrada personal ofrecido para el programa nombrado; nunca los incluya en el chat ni en campos ordinarios de apoyo.",
  "Saved information across requests": "Información guardada entre solicitudes",
  "When you start another request, we can fill your current household ZIP code from an earlier request you own. Your new authorization covers its use for the named programs, and you can edit it before starting. We keep the original source and date; reuse does not make it newly confirmed or extend its expiry. Changed information stops superseded work. Withdrawal, deletion or expiry stops reuse and removes the reused current value. Previously attempted packets and receipts keep their separate history and retention rules.": "Cuando inicia otra solicitud, podemos rellenar el código postal actual de su hogar a partir de una solicitud anterior que le pertenece. Su nueva autorización cubre su uso para los programas nombrados y puede editarlo antes de comenzar. Conservamos la fuente y la fecha originales; reutilizarlo no lo confirma de nuevo ni amplía su vencimiento. La información modificada detiene el trabajo basado en datos sustituidos. La retirada del permiso, la eliminación o el vencimiento detienen la reutilización y retiran el valor actual reutilizado. Los paquetes de información y comprobantes de intentos anteriores mantienen su propio historial y sus propias reglas de conservación.",
  "This does not copy private SNAP application answers, identifiers, signatures or a program-specific household or income definition into another program. We ask only for information that is still needed for the selected support and covered by its notice and permission.": "Esto no copia respuestas privadas de solicitudes de SNAP, identificadores, firmas ni una definición de hogar o ingresos específica de un programa a otro programa. Solo pedimos la información que aún se necesita para el apoyo elegido y que está cubierta por su aviso y permiso.",
  "Your shared family profile": "Su perfil familiar compartido",
  "When profile saving is available and you choose it, CaseLink stores the family basics you provide: contact details, home and mailing addresses, language, names, birth dates, relationships and known income-source types. You can leave questions unanswered and continue directly to support. Do not enter government identifiers, account access codes, passwords, pregnancy or medical details, citizenship answers or signatures here.": "Cuando guardar el perfil esté disponible y usted lo elija, CaseLink almacena los datos básicos de la familia que proporcione: datos de contacto, domicilios de residencia y correspondencia, idioma, nombres, fechas de nacimiento, parentescos y tipos conocidos de fuentes de ingresos. Puede dejar preguntas sin responder y continuar directamente al apoyo. No introduzca aquí identificadores gubernamentales, códigos de acceso a cuentas, contraseñas, datos de embarazo o médicos, respuestas sobre ciudadanía ni firmas.",
  "Your profile supplies compatible answers for support applications you choose and authorize. It does not give a program access to your profile or authorize a submission. Each confirmed answer is kept for up to 45 days; opening the profile or starting another request does not restart that time. You can update, download or clear your saved profile. Clearing or expiration stops future reuse. Copies in earlier application records follow their own stated purpose and retention rules. Corrections stop queued uses of superseded answers; already sent records stay in history.": "Su perfil aporta respuestas compatibles para las solicitudes de apoyo que elija y autorice. No da a un programa acceso a su perfil ni autoriza el envío de una solicitud. Cada respuesta confirmada se conserva hasta 45 días; abrir el perfil o iniciar otra solicitud no reinicia ese plazo. Puede actualizar, descargar o borrar su perfil guardado. Borrarlo o su vencimiento detienen la reutilización futura. Las copias en registros de solicitudes anteriores siguen su propia finalidad declarada y sus reglas de conservación. Las correcciones detienen los usos en cola de respuestas sustituidas; los registros ya enviados permanecen en el historial.",
  "Private SNAP application details": "Datos privados de la solicitud de SNAP",
  "When this collection purpose is enabled, the separate SNAP application fields request the ordinary answers needed for the reviewed Pennsylvania application: applicant name and postal address, optional phone contacts, language preferences, household members’ names and birth dates, relationship and student information, which people are applying and their citizenship answers, current-month income received or expected, applicable medical and other expense deductions and the form’s criminal-history and benefit-disqualification questions. Representative contact details are optional and do not designate CaseLink or an AI as an authorized representative. Optional race and voter-registration answers are not collected here.": "Cuando este fin de recopilación esté habilitado, los campos separados de la solicitud de SNAP piden las respuestas ordinarias necesarias para la solicitud revisada de Pensilvania: nombre y dirección postal del solicitante, contactos telefónicos opcionales, preferencias de idioma, nombres y fechas de nacimiento de los miembros del hogar, parentesco e información de estudios, qué personas solicitan beneficios y sus respuestas sobre ciudadanía, ingresos recibidos o previstos para el mes actual, deducciones médicas y de otros gastos aplicables, y las preguntas del formulario sobre antecedentes penales e inhabilitación para recibir beneficios. Los datos de contacto de un representante son opcionales y no designan a CaseLink ni a una IA como representante autorizado. Aquí no se recopilan las respuestas opcionales sobre raza ni inscripción electoral.",
  "Before these details are saved, the start authorization names Pennsylvania SNAP and explains the application purpose and information use. The answers are held in private, owned application revisions, separate from chat and ordinary support facts. Saving these answers does not send all of them to an AI service or submit an agency application. A future AI or delivery use must pass its actual purpose, information, processor and recipient controls. Required Social Security numbers, credentials and signature values are not accepted in these fields; genuine identifiers and certifications need a separately permitted protected process. The accepted submission route must establish its own personal act and receipt evidence.": "Antes de guardar estos datos, la autorización inicial nombra a SNAP de Pensilvania y explica la finalidad de la solicitud y el uso de la información. Las respuestas se conservan en versiones privadas de la solicitud que pertenecen a su titular, separadas del chat y de los datos ordinarios de apoyo. Guardarlas no las envía todas a un servicio de IA ni presenta una solicitud ante una agencia. Un uso futuro con IA o para el envío debe superar los controles reales de finalidad, información, encargado del procesamiento y destinatario. Estos campos no aceptan números de Seguro Social obligatorios, credenciales ni firmas; los identificadores y las certificaciones auténticos requieren un proceso protegido con permiso separado. La vía de presentación aceptada debe establecer sus propias pruebas del acto personal requerido y de la recepción.",
  "CaseLink keeps these application revisions while the support request is active and for up to 90 days after closure, subject to eligible earlier deletion. Unchanged answers keep their original recorded dates; reading them, starting another request or changing an unrelated answer does not refresh them. Corrections create a new revision and stop queued uses of superseded information. Earlier delivered records remain attributed history. These are sensitive household and eligibility details; the existing storage, access, deletion and backup limitations below apply. Real-family processing remains closed until its recorded privacy and operational checks are complete.": "CaseLink conserva estas versiones de la solicitud mientras la solicitud de apoyo está activa y hasta 90 días después del cierre, sujeto a una eliminación anterior cuando corresponda. Las respuestas que no cambian mantienen sus fechas originales registradas; leerlas, iniciar otra solicitud o cambiar una respuesta no relacionada no las actualiza. Las correcciones crean una nueva versión y detienen los usos en cola de información sustituida. Los registros entregados anteriormente permanecen en el historial con su atribución. Son datos sensibles del hogar y de elegibilidad; se aplican las limitaciones existentes de almacenamiento, acceso, eliminación y copias de seguridad que aparecen abajo. El procesamiento de información de familias reales sigue cerrado hasta que se completen las comprobaciones de privacidad y operativas registradas.",
  "Protected SNAP personal steps": "Pasos personales protegidos de SNAP",
  "When enabled, a separate permission names the people applying, the Pennsylvania SNAP application and the expiry before protected entry opens. Required Social Security numbers and your own signature drawings and dates are used to complete the private application. These entries stay out of AI, chat and ordinary household records. You can choose to provide an applicant’s Social Security number to the agency later; CaseLink does not invent one. Permission to collect these entries does not sign or send the application, or establish agency acceptance.": "Cuando esté habilitado, un permiso separado nombra a las personas solicitantes, la solicitud de SNAP de Pensilvania y el vencimiento antes de abrir la entrada protegida. Los números de Seguro Social obligatorios y los dibujos de sus propias firmas y fechas se usan para completar la solicitud privada. Estas entradas se mantienen fuera de la IA, el chat y los registros ordinarios del hogar. Puede optar por proporcionar después a la agencia el número de Seguro Social de una persona solicitante; CaseLink no inventa uno. El permiso para recopilar estas entradas no firma ni envía la solicitud ni establece su aceptación por la agencia.",
  "The approved CaseLink limit for the encrypted final SNAP PDF and its individual encryption key is at most 30 days from your original consent to this protected collection. Earlier permission or service-processing deadlines, withdrawal and deletion limits take precedence. Reading, recovering or following up on the application does not extend that deadline. This limit is separate from the ordinary application revisions above. An expiry date is not proof of completed deletion: scheduled PDF and key cleanup must be verified before live use. Processor copies, backups and records already delivered to a program have separate terms that must be resolved and explained before intake opens.": "El límite aprobado de CaseLink para el PDF final cifrado de SNAP y su clave individual de cifrado es de un máximo de 30 días desde su consentimiento original para esta recopilación protegida. Tienen prioridad los plazos anteriores del permiso o del procesamiento del servicio, así como los límites de retirada y eliminación. Leer, recuperar o hacer seguimiento de la solicitud no amplía ese plazo. Este límite es distinto del de las versiones ordinarias de la solicitud descritas arriba. Una fecha de vencimiento no es una prueba de que se haya completado la eliminación: antes del uso con datos reales debe verificarse la limpieza programada del PDF y de la clave. Las copias de los encargados del procesamiento, las copias de seguridad y los registros ya entregados a un programa tienen condiciones distintas que deben resolverse y explicarse antes de abrir la recepción de datos.",
  "What you authorize": "Qué autoriza",
  "Your support authorization names the programs, purposes, allowed actions and information, duration and attempt limits. You can choose research and preparation only. Work outside those limits requires new permission; routine permitted work inside them does not require you to approve every step.": "Su autorización de apoyo nombra los programas, fines, acciones e información permitidos, la duración y los límites de intentos. Puede elegir solo investigación y preparación. El trabajo fuera de esos límites requiere un nuevo permiso; el trabajo rutinario permitido dentro de ellos no requiere que apruebe cada paso.",
  "Preparation-only mode does not authorize external sharing, submissions or booking. Partnership with an organization does not by itself authorize an automated connection.": "El modo de solo preparación no autoriza compartir información externamente, presentar solicitudes ni reservar citas. La colaboración con una organización no autoriza por sí sola una conexión automatizada.",
  "Data policy: storage, access & security": "Política de datos: almacenamiento, acceso y seguridad",
  "CaseLink uses Supabase for account authentication, database and private file storage, and Vercel for the existing site. Hosting for the protected SNAP service has not been selected or activated. Access controls limit parent records to their household owner and specifically authorized service work. A school role or administrator role does not grant access to other parents’ household records. Any program access must be limited to the relevant referral and permission.": "CaseLink utiliza Supabase para autenticar cuentas, la base de datos y el almacenamiento privado de archivos, y Vercel para el sitio existente. El alojamiento del servicio protegido de SNAP no se ha seleccionado ni activado. Los controles de acceso limitan los registros de familias a la persona titular del hogar y al trabajo del servicio específicamente autorizado. Un rol escolar o de administración no concede acceso a registros de los hogares de otras familias. Cualquier acceso de un programa debe limitarse a la derivación y al permiso correspondientes.",
  "Security controls include authenticated sessions, database access rules, input checks, restricted document processing and server-side credential handling. We record limited activity and security information to operate and investigate the service. No system can promise complete security. Household details, uploaded content and AI prompts must not be copied into ordinary analytics, public links or notification previews.": "Los controles de seguridad incluyen sesiones autenticadas, reglas de acceso a la base de datos, comprobaciones de entradas, procesamiento restringido de documentos y gestión de credenciales en el servidor. Registramos información limitada de actividad y seguridad para operar e investigar el servicio. Ningún sistema puede prometer una seguridad completa. Los datos del hogar, el contenido subido y las instrucciones enviadas a la IA no deben copiarse a análisis ordinarios, enlaces públicos ni vistas previas de notificaciones.",
  "Ask CaseLink uses the question you send, your saved account preferences and relevant information from the request you select with OpenAI to answer. This includes permitted household facts, recorded progress and next steps. It does not include raw identity numbers, passwords or uploaded application documents. Sending a question records your agreement to this use; it does not submit an application or change your service permission.": "Preguntar a CaseLink utiliza con OpenAI la pregunta que envía, sus preferencias guardadas de la cuenta y la información pertinente de la solicitud que seleccione para responderle. Esto incluye datos del hogar permitidos, progreso registrado y próximos pasos. No incluye números de identidad en bruto, contraseñas ni documentos de solicitudes subidos. Enviar una pregunta registra su acuerdo con este uso; no presenta una solicitud ni cambia el permiso de su servicio.",
  "Bills, notices & AI processing": "Facturas, avisos y procesamiento con IA",
  "You must agree to document storage and processing before uploading or taking a photo through CaseLink. Supported files are JPEG, PNG or readable PDFs up to 10 MB and five pages. An unprocessed CaseLink raw copy expires after seven days. Successful extraction shortens raw-file expiry to at most 24 hours after validation. Validated facts may remain after the original file is removed. Private-file deletion is performed by the monitored cleanup process; an expiry date alone is not proof of completed erasure.": "Debe aceptar el almacenamiento y procesamiento de documentos antes de subirlos o tomar una foto mediante CaseLink. Se admiten archivos JPEG, PNG o PDF legibles de hasta 10 MB y cinco páginas. Una copia original de CaseLink sin procesar vence después de siete días. Una extracción correcta acorta el vencimiento del archivo original a un máximo de 24 horas después de la validación. Los datos validados pueden permanecer después de retirar el archivo original. La eliminación de archivos privados se realiza mediante el proceso de limpieza supervisado; una fecha de vencimiento por sí sola no demuestra que se haya completado el borrado.",
  "Where enabled and approved, OpenAI’s Responses service receives minimized routing facts or selected provider, financial and date lines to help prepare support steps. Whole bills are parsed in a separate restricted environment. OpenAI API content is not used for training by default; standard abuse-monitoring retention can be up to 30 days, with stated exceptions, and encrypted prompt-cache state can persist up to 24 hours. Our store:false setting is not approval for Zero Data Retention. Facts must be checked and remain connected to their source. Uploaded content does not give an AI new permissions. Files are stored privately and should not be placed in public links, analytics or a browser storage vault.": "Cuando esté habilitado y aprobado, el servicio Responses de OpenAI recibe los datos mínimos de orientación a programas o líneas seleccionadas de proveedor, finanzas y fechas para ayudar a preparar los pasos de apoyo. Las facturas completas se analizan en un entorno restringido separado. El contenido de la API de OpenAI no se utiliza para entrenamiento de forma predeterminada; la conservación estándar para supervisar abusos puede durar hasta 30 días, con las excepciones indicadas, y el estado cifrado de la caché de instrucciones puede persistir hasta 24 horas. Nuestra configuración store:false no constituye una aprobación de Retención Cero de Datos. Los datos deben comprobarse y permanecer vinculados a su fuente. El contenido subido no otorga nuevos permisos a una IA. Los archivos se almacenan de forma privada y no deben ponerse en enlaces públicos, análisis ni un almacén del navegador.",
  "Before live processing, the service must publish its approved processor, retention, deletion and disclosure terms. A test configuration is not a privacy certification. See": "Antes del procesamiento con datos reales, el servicio debe publicar las condiciones aprobadas de sus encargados del procesamiento, conservación, eliminación y divulgación. Una configuración de prueba no es una certificación de privacidad. Consulte",
  "OpenAI’s API data controls": "los controles de datos de la API de OpenAI",
  "for its current terms. CaseLink’s AI service is separate from your personal ChatGPT account; you do not need a ChatGPT account to use CaseLink.": "para conocer sus condiciones actuales. El servicio de IA de CaseLink es independiente de su cuenta personal de ChatGPT; no necesita una cuenta de ChatGPT para usar CaseLink.",
  "Cookies, messages & technical information": "Cookies, mensajes e información técnica",
  "When you choose a screen language, a cookie remembers English or Spanish in this browser for up to 90 days. It contains no household facts and does not change your program contact language or service permission. Clearing this cookie removes that browser preference.": "Cuando elige un idioma de pantalla, una cookie recuerda inglés o español en este navegador durante hasta 90 días. No contiene datos del hogar ni cambia el idioma de contacto con los programas o el permiso del servicio. Borrar esta cookie elimina esa preferencia del navegador.",
  "Necessary cookies keep you signed in and protect your session. Hosting, authentication and security services also process request times, IP addresses and related network information. We do not add advertising or cross-site tracking cookies, or use third-party advertising analytics.": "Las cookies necesarias mantienen la sesión iniciada y la protegen. Los servicios de alojamiento, autenticación y seguridad también procesan horas de solicitudes, direcciones IP e información de red relacionada. No añadimos cookies publicitarias ni de seguimiento entre sitios, ni usamos análisis publicitarios de terceros.",
  "If you choose email updates and the service is enabled, Resend delivers a general notice with a link to sign in. The message does not include your program, income, utility balance or support outcome. Email delivery still shares your email address and delivery metadata with the email provider. You can change optional update preferences in your account; sign-in and necessary security messages are separate.": "Si elige actualizaciones por correo electrónico y el servicio está habilitado, Resend envía un aviso general con un enlace para iniciar sesión. El mensaje no incluye su programa, ingresos, saldo de servicios públicos ni resultado del apoyo. El envío de correo sigue compartiendo su dirección y los datos de entrega con el proveedor de correo. Puede cambiar las preferencias opcionales de actualizaciones en su cuenta; los mensajes de inicio de sesión y de seguridad necesarios son independientes.",
  "Sharing with programs": "Información compartida con los programas",
  "Only specifically authorized information can be sent through a verified permitted program channel. Each attempt keeps its exact packet and recorded evidence. Prepared, sent, received, accepted, submitted, approved and support received have different meanings.": "Solo puede enviarse información específicamente autorizada a través de un canal del programa verificado y permitido. Cada intento conserva su paquete exacto de información y las pruebas registradas. Preparado, enviado, recibido, aceptado, presentado, aprobado y apoyo recibido tienen significados distintos.",
  "A program may keep delivered information under its own rules. Cancelling future CaseLink work cannot always recall something already delivered or withdraw an agency application.": "Un programa puede conservar la información entregada según sus propias reglas. Cancelar el trabajo futuro de CaseLink no siempre permite recuperar algo ya entregado ni retirar una solicitud de una agencia.",
  "Information may also be disclosed where legally required. Service providers receive only the information needed for approved functions, under the applicable terms. Recognition through OpenAI’s ChatGPT Futures program does not give OpenAI or a school access to your CaseLink account.": "La información también puede divulgarse cuando la ley lo exija. Los proveedores de servicios reciben solo la información necesaria para las funciones aprobadas, bajo las condiciones aplicables. El reconocimiento del programa ChatGPT Futures de OpenAI no da a OpenAI ni a una escuela acceso a su cuenta de CaseLink.",
  "Corrections, pause & cancellation": "Correcciones, pausa y cancelación",
  "Correct important information on your request page. Corrections stop queued uses of superseded facts and flag any already delivered packet that may need an update. Previously submitted versions stay in the recorded history.": "Corrija la información importante en la página de su solicitud. Las correcciones detienen los usos en cola de datos sustituidos y señalan cualquier paquete ya entregado que pueda necesitar una actualización. Las versiones presentadas anteriormente permanecen en el historial registrado.",
  "You can pause or cancel future work in": "Puede pausar o cancelar el trabajo futuro en",
  ". Signing out secures the device; it does not revoke an active service authorization.": ". Cerrar la sesión protege el dispositivo; no revoca una autorización activa del servicio.",
  "Download or delete": "Descargar o eliminar",
  "Use": "Use",
  "to download your recorded parent-service information or request deletion. Deletion stops future parent-service work and blocks parent access, with private-file cleanup and eligible-record removal handled through the deletion process. It does not delete a reused CaseLink sign-in identity or school records held for a separate purpose. Contact us for a broader account or privacy request. The proposed CaseLink schedule keeps ordinary service records and nonprotected packets during active service and for 90 days after closure, subject to earlier eligible deletion. The protected SNAP PDF and key instead have the shorter limit described above. Selected minimal evidence hashes and deletion tombstones have a proposed 365-day expiry. These periods require an approved purpose; they are not a claim that a law requires them. Backups, processor copies and delivered program records follow separately approved terms. The final notice must describe those limits before intake opens.": "para descargar su información registrada del servicio para familias o solicitar su eliminación. La eliminación detiene el trabajo futuro del servicio para familias y bloquea el acceso al servicio para familias, con limpieza de archivos privados y retirada de registros cuando corresponda mediante el proceso de eliminación. No elimina una identidad reutilizada de inicio de sesión de CaseLink ni registros escolares conservados para otro fin. Contáctenos para una solicitud más amplia sobre la cuenta o la privacidad. El calendario propuesto de CaseLink conserva los registros ordinarios del servicio y los paquetes no protegidos durante el servicio activo y durante 90 días después del cierre, sujeto a una eliminación anterior cuando corresponda. El PDF protegido de SNAP y su clave tienen, en cambio, el límite más breve descrito arriba. Los hashes mínimos seleccionados de pruebas y los registros que impiden restablecer datos eliminados tienen un vencimiento propuesto de 365 días. Estos plazos requieren una finalidad aprobada; no afirman que una ley los exija. Las copias de seguridad, las copias de los encargados del procesamiento y los registros entregados a programas siguen condiciones aprobadas por separado. El aviso final debe describir esos límites antes de abrir la recepción de datos.",
  "Shared devices & account access": "Dispositivos compartidos y acceso a la cuenta",
  "Use an email you control, keep your password and codes private, and sign out on shared devices. Where existing-account access is enabled, use your existing CaseLink email and password. First use of the parent service creates your own household space; it does not grant permission to use someone else’s records. Signing out of the parent service does not sign you out of a separate school workspace session.": "Use un correo electrónico que controle, mantenga su contraseña y códigos privados y cierre la sesión en dispositivos compartidos. Cuando esté habilitado el acceso con cuentas existentes, use su correo y contraseña actuales de CaseLink. El primer uso del servicio para familias crea un espacio para su propio hogar; no concede permiso para usar los registros de otra persona. Cerrar la sesión del servicio para familias no cierra una sesión separada en el espacio de trabajo escolar.",
  "Children & caregivers": "Menores y cuidadores",
  "Accounts are for adults and authorized caregivers. A child does not need an account. Provide information about a child only when you have the authority to do so and it is needed for the chosen support. Contact us if you believe a child has created an account or information was provided without appropriate authority.": "Las cuentas son para personas adultas y cuidadores autorizados. Un menor no necesita una cuenta. Proporcione información sobre un menor solo cuando tenga autoridad para hacerlo y sea necesaria para el apoyo elegido. Contáctenos si cree que un menor ha creado una cuenta o se ha proporcionado información sin la autoridad adecuada.",
  "Questions, requests & policy changes": "Preguntas, solicitudes y cambios de política",
  "William Sanz operates CaseLink as an individual, without a registered entity, and is responsible for privacy and incident requests. Contact him at": "William Sanz gestiona CaseLink como persona física, sin una entidad registrada, y es responsable de las solicitudes de privacidad y de incidentes. Contacte con él en",
  ". Use it for privacy questions, access or deletion requests, corrections you cannot make in the app, or security concerns. Do not attach bills, identity documents, passwords or codes to email. We may need to verify a request before releasing or deleting information.": ". Úselo para preguntas de privacidad, solicitudes de acceso o eliminación, correcciones que no pueda hacer en la aplicación o problemas de seguridad. No adjunte facturas, documentos de identidad, contraseñas ni códigos al correo electrónico. Es posible que necesitemos verificar una solicitud antes de entregar o eliminar información.",
  "Use the official program contacts in": "Use los contactos oficiales de los programas en",
  "for their privacy practices and alternatives to CaseLink. We date changes to this notice and seek new permission when a change expands your authorization. The monitored privacy response process and final processor and retention terms must be confirmed before real-family intake opens.": "para conocer sus prácticas de privacidad y alternativas a CaseLink. Fechamos los cambios de este aviso y solicitamos un nuevo permiso cuando un cambio amplía su autorización. El proceso supervisado de respuesta a solicitudes de privacidad y las condiciones finales de los encargados del procesamiento y de conservación deben confirmarse antes de abrir la recepción de datos de familias reales.",
  "Clear expectations for support.": "Expectativas claras para recibir apoyo.",
  "Last updated October 25, 2026 · Parent service": "Última actualización: 25 de octubre de 2026 · Servicio para familias",
  "Who this service is for": "A quién está dirigido este servicio",
  "The parent service is for adults seeking food support or utility assistance for their household, and caregivers with the necessary authority. Philadelphia is the initial service area; each program has its own coverage, requirements and availability.": "El servicio para familias está dirigido a personas adultas que buscan apoyo alimentario o asistencia con servicios públicos para su hogar, y a cuidadores con la autoridad necesaria. Filadelfia es el área de servicio inicial; cada programa tiene su propia cobertura, requisitos y disponibilidad.",
  "Use CaseLink lawfully and only for information you have authority to provide. Do not impersonate another person, access another household, disrupt the service or try to bypass its safeguards. These terms cover parent support; a school’s separate service arrangements and records rules continue to apply to its workspace.": "Use CaseLink conforme a la ley y proporcione solo información que tenga autoridad para facilitar. No se haga pasar por otra persona, no acceda a otro hogar, no interrumpa el servicio ni intente eludir sus protecciones. Estos términos cubren el apoyo para familias; los acuerdos de servicio y las reglas sobre registros de cada escuela siguen aplicándose a su espacio de trabajo.",
  "Where enabled, your existing CaseLink email and password work for the parent service. Email-code access is also available for supported account creation and recovery. Keep credentials private and use an email you control. A shared sign-in does not copy school records or grant access to anyone else’s household. Tell us if you believe your account has been misused.": "Cuando esté habilitado, puede usar su correo electrónico y contraseña actuales de CaseLink para el servicio para familias. El acceso con código por correo también está disponible para la creación y recuperación de cuentas admitidas. Mantenga sus credenciales privadas y use un correo electrónico que controle. Compartir el inicio de sesión entre servicios no copia registros escolares ni concede acceso al hogar de otra persona. Avísenos si cree que alguien ha usado indebidamente su cuenta.",
  "What CaseLink can do": "Qué puede hacer CaseLink",
  "Within an informed, bounded authorization, CaseLink can research, prepare and carry out supported steps through verified permitted channels. Your request shows its actual capability limits. A preparation summary, referral or appointment request is not proof of an application, approval or assistance received.": "Dentro de una autorización informada y delimitada, CaseLink puede investigar, preparar y realizar pasos admitidos a través de canales verificados y permitidos. Su solicitud muestra los límites reales de las funciones disponibles. Un resumen de preparación, una derivación o una petición de cita no demuestra que se haya presentado una solicitud, concedido una aprobación o recibido asistencia.",
  "What stays yours": "Qué sigue siendo su responsabilidad",
  "Provide accurate information to the best of your knowledge and correct it when circumstances change. Required identity checks, personal attestations, signatures, interviews and meaningful financial decisions stay with you or the authorized professional. CaseLink does not sign as you, make agency eligibility decisions or accept binding financial arrangements under a general service authorization.": "Proporcione información exacta según su leal saber y entender y corríjala cuando cambien las circunstancias. Las verificaciones de identidad, declaraciones personales, firmas, entrevistas y decisiones económicas importantes que se requieran siguen correspondiéndole a usted o al profesional autorizado. CaseLink no firma en su nombre, no decide la elegibilidad de los programas ni acepta acuerdos económicos vinculantes bajo una autorización general de servicio.",
  "AI can make mistakes. CaseLink checks supported information and execution permissions, but its assistance is not legal, medical or financial advice. Correct important facts when you notice an error; use a qualified professional or the official program for decisions that require one. We will not ask you to approve every routine action already covered by your authorization.": "La IA puede equivocarse. CaseLink comprueba la información admitida y los permisos de ejecución, pero su ayuda no constituye asesoramiento legal, médico ni financiero. Corrija los datos importantes cuando vea un error; acuda a un profesional cualificado o al programa oficial para las decisiones que lo requieran. No le pediremos que apruebe cada acción rutinaria ya cubierta por su autorización.",
  "No guaranteed award or availability": "No se garantiza una ayuda ni su disponibilidad",
  "Programs and agencies decide eligibility and assistance. Funding, food availability, appointments and processing times can change. CaseLink cannot guarantee an award, a shutoff hold, restored service or a particular response time. Use official program channels for time-sensitive needs.": "Los programas y las agencias deciden la elegibilidad y la asistencia. Los fondos, la disponibilidad de alimentos, las citas y los plazos de tramitación pueden cambiar. CaseLink no puede garantizar una ayuda, la suspensión de un corte, el restablecimiento de un servicio ni un plazo de respuesta concreto. Use los canales oficiales de los programas para necesidades urgentes.",
  "Your permission has limits": "Su permiso tiene límites",
  "The start authorization specifies named programs, information, actions, duration and attempts. In-scope work can continue after you close the page or sign out. You may pause or cancel future work. New recipients, purposes or expanded permissions require your authorization.": "La autorización inicial especifica los programas nombrados, la información, las acciones, la duración y los intentos. El trabajo autorizado puede continuar después de cerrar la página o la sesión. Puede pausar o cancelar el trabajo futuro. Los nuevos destinatarios, fines o permisos ampliados requieren su autorización.",
  "Your information": "Su información",
  "Read the": "Lea el",
  "privacy and control notice": "aviso de privacidad y control",
  "before sharing. Documents require their own processing consent. Never share passwords, sign-in codes or EBT PINs through a support request.": "antes de compartir información. Los documentos requieren su propio consentimiento de procesamiento. No comparta nunca contraseñas, códigos de inicio de sesión ni PIN de EBT mediante una solicitud de apoyo.",
  "Direct access & help": "Acceso directo y ayuda",
  "You may apply directly or use a qualified person at any time. CaseLink does not replace required program specialists, legal advice or emergency services.": "Puede solicitar ayuda directamente o acudir a una persona cualificada en cualquier momento. CaseLink no sustituye a los especialistas que exijan los programas, el asesoramiento legal ni los servicios de emergencia.",
  "keeps official options accessible without an account.": "mantiene disponibles las opciones oficiales sin necesidad de una cuenta.",
  "Availability, safety & ending use": "Disponibilidad, seguridad y fin del uso",
  "Service features can change or be interrupted. We may restrict access to address misuse or security concerns. You can stop using the service, cancel future work or request parent-service deletion. Parent deletion does not delete a reused sign-in identity or separately held school records. Keep copies of records you need and use official alternatives for urgent needs. Mandatory consumer rights remain in place.": "Las funciones del servicio pueden cambiar o interrumpirse. Podemos restringir el acceso para responder al uso indebido o a problemas de seguridad. Puede dejar de usar el servicio, cancelar el trabajo futuro o solicitar la eliminación de sus datos del servicio para familias. Esta eliminación no borra una identidad de inicio de sesión reutilizada ni registros escolares conservados por separado. Guarde copias de los registros que necesite y use alternativas oficiales para necesidades urgentes. Los derechos obligatorios de las personas consumidoras siguen vigentes.",
  "CaseLink & OpenAI": "CaseLink y OpenAI",
  "CaseLink is a separate service using OpenAI technology where enabled. The original site’s ChatGPT Futures recognition and grant acknowledgment describe that program participation; they do not mean that OpenAI operates CaseLink or guarantees assistance. CaseLink’s name and logo identify this service. OpenAI and ChatGPT names and marks belong to OpenAI.": "CaseLink es un servicio independiente que utiliza tecnología de OpenAI cuando está habilitada. El reconocimiento ChatGPT Futures y la mención de la subvención del sitio original describen la participación en ese programa; no significan que OpenAI gestione CaseLink ni garantice asistencia. El nombre y el logotipo de CaseLink identifican este servicio. Los nombres y las marcas de OpenAI y ChatGPT pertenecen a OpenAI.",
  "Contact & changes": "Contacto y cambios",
  "For questions about these terms, contact": "Para preguntas sobre estos términos, contacte con",
  ". Do not send sensitive documents or credentials by email. We date updates to these terms and obtain new authorization when the work you permit expands. The final service operator details, support coverage and approved terms must be confirmed before real-family intake opens. Current test use must remain synthetic.": ". No envíe documentos sensibles ni credenciales por correo electrónico. Fechamos las actualizaciones de estos términos y obtenemos una nueva autorización cuando se amplía el trabajo que usted permite. Los datos definitivos del responsable del servicio, la cobertura del apoyo y los términos aprobados deben confirmarse antes de abrir la recepción de datos de familias reales. El uso actual de prueba debe seguir empleando información sintética.",
  "Help & direct support": "Ayuda y apoyo directo",
  "Official food and utility support in Philadelphia, account recovery and answers about CaseLink.": "Apoyo alimentario y de servicios públicos oficial en Filadelfia, recuperación de cuentas y respuestas sobre CaseLink.",
  "How CaseLink uses household information, documents and AI, and how you control your support.": "Cómo usa CaseLink la información del hogar, los documentos y la IA, y cómo controla usted su apoyo.",
  "Clear expectations for using CaseLink’s parent food and utility support service.": "Expectativas claras para usar el servicio de apoyo alimentario y de servicios públicos de CaseLink para familias.",
  "Email-code sign-in is available for supported parent accounts; it does not replace a school account’s password check.": "El inicio de sesión con un código por correo está disponible para las cuentas de familias admitidas; no sustituye la comprobación de contraseña de una cuenta escolar.",
  "The food-location tool below remains in English.": "La herramienta para buscar lugares con alimentos que aparece abajo sigue en inglés.",
  "Philadelphia food and meal finder": "Buscador de alimentos y comidas de Filadelfia",
  "Find city-listed food and meal locations. Confirm hours, pickup requirements and availability before traveling.": "Busque lugares de alimentos y comidas incluidos en las listas de la Ciudad. Confirme los horarios, requisitos de recogida y disponibilidad antes de ir.",
  "Share Community Fridge · Hunting Park": "Refrigerador comunitario de Share · Hunting Park",
  "Prepare public walk-up instructions for Share's community fridge at 2901 W Hunting Park Ave, 19129. Food depends on donations; stock is unknown and nothing is reserved.": "Prepare indicaciones de acceso público sin cita al refrigerador comunitario de Share en 2901 W Hunting Park Ave, 19129. Los alimentos dependen de donaciones; se desconoce qué hay disponible y no se reserva nada.",
  "Pennsylvania SNAP": "SNAP de Pensilvania",
  "Apply, renew or follow an existing SNAP application through Pennsylvania's official benefits service. A new application can begin without creating a COMPASS account. DHS determines eligibility.": "Solicite o renueve SNAP, o haga seguimiento de una solicitud existente, mediante el servicio oficial de beneficios de Pensilvania. Puede iniciar una solicitud nueva sin crear una cuenta de COMPASS. DHS determina la elegibilidad.",
  "Pennsylvania WIC": "WIC de Pensilvania",
  "Coordinate WIC enrollment, continuing support, documents and a specialist appointment.": "Coordine la inscripción en WIC, el apoyo continuo, los documentos y una cita con un especialista.",
  "UESF benefits assistance": "Asistencia con beneficios de UESF",
  "Partner benefits navigation and help with a supported application or benefit problem.": "Orientación sobre beneficios de una organización asociada y ayuda con una solicitud admitida o un problema con los beneficios.",
  "UESF utility assistance": "Asistencia con servicios públicos de UESF",
  "Philadelphia utility grant assistance. Funding, account requirements and any required contribution must be confirmed by the program.": "Asistencia mediante ayudas económicas para servicios públicos en Filadelfia. El programa debe confirmar los fondos, los requisitos de la cuenta y cualquier aportación obligatoria.",
  "PECO assistance programs": "Programas de asistencia de PECO",
  "Explore PECO affordability and assistance options for an electric bill or threatened interruption.": "Explore las opciones de PECO para hacer más asequible una factura de electricidad o recibir ayuda ante un posible corte.",
  "Explore PGW financial support, affordability and energy assistance options.": "Explore las opciones de PGW de apoyo económico, tarifas asequibles y asistencia energética.",
  "Use the City's water assistance application route. The City does not accept application documents by email.": "Use la vía de solicitud de asistencia para el agua de la Ciudad. La Ciudad no acepta documentos de solicitudes por correo electrónico.",
} as const;
